static void settings_calculator_timer_event_cb(struct _lv_timer_t *timer)
{
    if (settings_calculator_timer) {
        lv_timer_del(settings_calculator_timer);
        settings_calculator_timer = NULL;
        lv_obj_add_flag(ui_FpToolsCalculatorHint,LV_OBJ_FLAG_HIDDEN); /// Flags
        lv_obj_add_flag(ui_FpToolsCalculatorDivZero,LV_OBJ_FLAG_HIDDEN); /// Flags

        }
}


void settings_calculator_timer_start(uint8_t type)
{

    if (settings_calculator_timer == NULL) {
        settings_calculator_timer = lv_timer_create(settings_calculator_timer_event_cb,1500,0);

        if (type)
            lv_obj_clear_flag(ui_FpToolsCalculatorDivZero,LV_OBJ_FLAG_HIDDEN); /// Flags
        else 
            lv_obj_clear_flag(ui_FpToolsCalculatorHint,LV_OBJ_FLAG_HIDDEN); /// Flags
        }

}


